// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }

    function testFuzz_property(uint256 probe) public {
        // keep the fuzz domain wide; the deciding observation is c's public paused() getter
        vm.assume(probe < type(uint256).max);

        // The contract has never been paused (no pause()/unpause() action was taken),
        // so a truthful paused() view must report the actual pause state: false.
        assertTrue(c.paused() == false);
    }
}
